    async handleLogin() {
      this.isLoading = true
      try {
        if (this.username && this.password) {
          const { username, password } = this
          const result = await this.$storex.api.users.login({ username, password })
          if (!result) {
            this.$storex.session.onError("Invalid user name or password")
          } else {
            window.location.reload()
          }
        }
      } catch (error) {
        console.error('Login error:', error)
        this.$storex.session.onError("Login failed: " + (error?.message || error))
      } finally {
        this.isLoading = false
      }
    },
    async handleGithubLogin() {
      this.isLoading = true
      try {
        const response = await this.$storex.api.oauth.getOAuthLoginUrl('github')
        const authUrl = response?.auth_url || response

        if (!authUrl) {
          this.$storex.session.onError("Invalid OAuth response: no URL provided")
          return
        }

        window.location.href = authUrl
      } catch (error) {
        console.error('GitHub login error:', error)
        this.$storex.session.onError("Failed to initiate GitHub login: " + (error?.message || error))
      } finally {
        this.isLoading = false
      }
    }
  }
}
</script>
