        return data
      },
      get workspaces() {
        if (!API._workspaceModule) {
          API._workspaceModule = workspacesModule(API)
        }
        return API._workspaceModule
      },
    },

    github: {
      issues: {
        helpWanted(query) {
          const qs = query ? `?query=${encodeURIComponent(query)}` : ''
          return API.get(`/api/github/issues/help-wanted${qs}`)
        },
        read(issueUrl) {
