        },
        async process(issueUrl) {
          return await API.get(`/api/github/issues/ai/process?issue_url=${encodeURIComponent(issueUrl)}`)
        }
      }
    },
    repo: {
      info() {
        return API.get('/api/git/repo/info')
      },
      branches() {
        return API.get('/api/git/repo/branches')
      },
      commits(branch) {
